@spec tuning_spec  src=tests/specs/tuning_spec.lua  loc=707  cases=47
@exercises tuning (tuning)
@surface   tuning.derive, tuning.stepToParts, tuning.genRank2, tuning.stepToMidi, tuning.midiToStep, tuning.scalaPitch, tuning.unrooted, tuning.removeStep, tuning.sortSteps, tuning.midiName, tuning.stepWindow, tuning.parseScalaFile, tuning.parseScalaPitches, tuning.scalaToTemper, tuning.genEqual, tuning.edoDegrees, tuning.degreesToSpec, tuning.genHarmonics, tuning.genSubharmonics, tuning.parseChord, tuning.genChord, tuning.genCPS, tuning.genDiamond, tuning.nextMosSize, tuning.mosInfo

# Intent
  Pins tuning.lua's pure display + derivation layer: the Option-B nameless
  step labels, the derived octaveStep / cellWidth fields, and the coordinate
  conversions between MIDI and step-octave. Realisation invariants (I1-I5)
  live in tm_tuning_spec; projection wiring in view_context_spec.

# Helpers
  @fn nameless(cents)  @ 10-12
  @fn stepText(temper, step, octave)  @ 16-19
      -- The two label parts joined, so a case that is about the whole label can
      -- assert it as one string.
  @fn rooted(root)  @ 22-28
      -- A 12EDO scale with the root fields the case is about; everything else default.
  @fn authored(root)  @ 32-37
      -- The same 12EDO in the shape a step edit sees: pitch tokens, names densified
      -- to '' as cloneForEdit leaves them, so sortSteps and removeStep can drive it.
  @fn meantone12()  @ 41-45
      -- Quarter-comma meantone's twelve-note MOS (Eb..G#, C at the unison): an
      -- unequal scale, so a step's two neighbours sit at different distances.
  @fn soundsA415(temper, step, why)  @ 53-57
      -- What the rooted step sounds, as (midi, detune); the deletions and sorts below
      -- all claim to leave it alone.

# Cases
  @case 'preset EDOs derive width 3 and a past-the-end octaveStep'  [pure]  @ 61-71
  @case 'named step renders name + octave'  [pure]  @ 75-80
  @case 'a negative octave renders as its magnitude and reports the sign'  [pure]  @ 84-93
  @case 'the octaveStep bump owns the sign: a step that crosses zero is not negative'  [pure]  @ 97-104
  @case 'nameless step falls back to degree-octave with a dash'  [pure]  @ 108-116
  @case 'nameless scale past 9 steps widens the cell for 2-digit degrees'  [pure]  @ 120-127
  @case 'sub-octave period widens the octave field for 2-digit octaves'  [pure]  @ 131-140
  @case 'a root numbering the octaves near zero narrows the field'  [pure]  @ 144-164
  @case 'a root numbering the range low makes the bottom end the wider'  [pure]  @ 168-180
  @case 'derive recomputes width when names are dropped'  [pure]  @ 184-192
  @case 'partially named scale: named steps keep their label, blanks fall back'  [pure]  @ 196-203
  @case 'scalaPitch parses ratios, cents, bare integers and n\\m steps'  [pure]  @ 207-221
  @case 'derive compiles pitches → cents and periodPitch → period'  [pure]  @ 225-233
  @case 'derive reduces an authored root to rootCents + octaveBase'  [pure]  @ 237-247
  @case 'a preset states no root and derives the default (0,0) = (1,-1)'  [pure]  @ 251-260
  @case 'unrooted is the library form: the four dropped, the stamps back at the default'  [pure]  @ 264-275
  @case 'a deleted step takes the root\'s index down with it'  [pure]  @ 279-289
  @case 'deleting the rooted step restates the root on the unison'  [pure]  @ 293-310
  @case 'a step sorted below the root carries the root\'s index'  [pure]  @ 314-323
  @case 'retuning the rooted step moves the scale, not the root'  [pure]  @ 327-340
  @case 'a temper stating no root comes through both edits unstamped'  [pure]  @ 344-355
  @case 'midiName spells a pitch in the untempered twelve names'  [pure]  @ 359-365
  @case 'the default root reduces the conversions to MIDI-relative arithmetic'  [pure]  @ 369-384
  @case 'stepWindow halves the distance to each neighbour, wrapping at both ends'  [pure]  @ 388-401
  @case 'stepWindow under an unequal scale reports two different halves'  [pure]  @ 405-417
  @case 'a flattened root moves every pitch by its offset and renames nothing'  [pure]  @ 421-443
  @case 'an octave-shifted root renames every octave and moves no pitch'  [pure]  @ 447-463
  @case 'the conversions invert each other at every root'  [pure]  @ 467-480
  @case 'EDO presets carry n\\m source tokens that derive back to their cents'  [pure]  @ 484-491
  @case 'parseScalaFile strips comments, description and count; returns pitch tokens'  [pure]  @ 495-503
  @case 'parseScalaPitches keeps every non-comment, non-blank line'  [pure]  @ 507-512
  @case 'scalaToTemper prepends the unison, splits the period, flags periodAsStep'  [pure]  @ 516-527
  @case 'scalaToTemper sorts unordered pitches ascending; widest becomes the period'  [pure]  @ 531-540
  @case 'scalaToTemper rejects an unparseable token'  [pure]  @ 544-549
  @case 'genEqual: full EDO and a diatonic subset, base implicit, period last'  [pure]  @ 553-565
  @case 'edoDegrees: relative cumulates, absolute sorts; non-octave equave suffixes'  [pure]  @ 569-577
  @case 'degreesToSpec round-trips edoDegrees in both modes'  [pure]  @ 581-585
  @case 'genHarmonics / genSubharmonics: rooted on the low harmonic, top is period'  [pure]  @ 589-598
  @case 'genChord: otonal vs inverted, last member is the period'  [pure]  @ 602-614
  @case 'parseChord rejects fewer than two notes or non-integers'  [pure]  @ 618-622
  @case 'genCPS: hexany rooted on the smallest product, 1/1 first, ascending'  [pure]  @ 626-632
  @case 'genDiamond: the 9-diamond entire, and the counts either side of it'  [pure]  @ 636-646
  @case 'genDiamond: the prime limit filters in place, and leaves a tritone hole'  [pure]  @ 650-661
  @case 'genRank2: pure-fifth size 7 / up 5 is Pythagorean major, 1/1 first'  [pure]  @ 665-671
  @case 'genRank2: size 4 / up 2 matches the Scale Workshop worked example'  [pure]  @ 675-680
  @case 'genRank2: irrational (EDO-step) generator emits cents tokens'  [pure]  @ 684-689
  @case 'nextMosSize / mosInfo: pure-fifth ladder 2->3->5->7->12; 7 is 5L 2s'  [pure]  @ 693-705

